"""Exact reference kernel for DECLARED bad-path nulls, not a sensor verifier.

Each path is a fixed convex mixture of tests whose nulls all hold if that path
is feasible. The complete path list, nonempty model, score/measurement mapping,
conditional means, protected receipts, and predictable bets are EXTERNAL premises.
No networking, deployment, automatic modification, or hidden-origin validation.
"""
from fractions import Fraction as Q


def rational(x):
    if isinstance(x, bool) or not isinstance(x, (int, str, Q)):
        raise ValueError('Use integers, rational strings, or Fraction; no floats')
    return Q(x)


class PathEvidence:
    """Sequential commit/resolve protocol; a missing outcome counts as zero.

    The API enforces call order, not genuine chronology or data authenticity.
    Reusing this object with new hidden data/model semantics is not authorized.
    """
    def __init__(self, thresholds, paths, alpha=Q(1,16), domain='NONEMPTY'):
        self.alpha = rational(alpha)
        if not 0 < self.alpha < 1:
            raise ValueError('alpha must be in (0,1)')
        if domain not in ('NONEMPTY','EMPTY','UNKNOWN'):
            raise ValueError('Invalid domain status')
        self.domain = domain
        self.c = {j:rational(x) for j,x in thresholds.items()}
        if any(not 0 < x < 1 for x in self.c.values()):
            raise ValueError('This kernel requires thresholds strictly in (0,1)')
        self.paths = {}
        for p, weights in paths.items():
            w = {j:rational(x) for j,x in weights.items()}
            if any(j not in self.c or x < 0 for j,x in w.items()):
                raise ValueError('Invalid mixture component')
            if w and sum(w.values(), Q(0)) != 1:
                raise ValueError('Nonempty path mixtures must sum to one')
            # Empty mixture denotes an unblocked path, NOT a missing path.
            self.paths[p] = w
        self.wealth = {j:Q(1) for j in self.c}
        self.hit = {p:False for p in self.paths}
        self.first_hit = {}
        self.attempts = self.resolved = self.missing = 0
        self.pending = None
        self.invalid = False

    def require(self, ok, reason):
        if not ok:
            self.invalid = True
            raise ValueError(reason)

    def commit(self, test, bet):
        """Record an attempted query and its bet BEFORE the outcome is seen."""
        self.require(not self.invalid and self.pending is None, 'Invalid/pending audit')
        self.require(test in self.c, 'Unknown test')
        try:
            bet = rational(bet)
        except (ValueError, ZeroDivisionError):
            self.invalid = True
            raise
        self.require(0 <= bet <= 1/self.c[test], 'Bet violates nonnegativity bound')
        self.attempts += 1
        self.pending = (self.attempts, test, bet)
        return self.attempts

    def resolve(self, receipt, value):
        """Resolve EVERY receipt once, with truthful [0,1] value or None."""
        self.require(not self.invalid and self.pending is not None, 'No pending query')
        index, test, bet = self.pending
        self.require(type(receipt) is int and receipt == index, 'Wrong receipt')
        try:
            x = Q(0) if value is None else rational(value)
        except (ValueError, ZeroDivisionError):
            self.invalid = True
            raise
        self.require(0 <= x <= 1, 'Outcome outside declared range')
        self.wealth[test] *= 1 + bet*(x-self.c[test])
        self.missing += value is None
        self.resolved += 1
        self.pending = None
        for p, weights in self.paths.items():
            current = sum((w*self.wealth[j] for j,w in weights.items()), Q(0)) if weights else Q(1)
            if not self.hit[p] and current >= 1/self.alpha:
                self.hit[p] = True
                self.first_hit[p] = self.resolved

    def snapshot(self):
        if self.invalid or self.pending is not None or self.domain != 'NONEMPTY':
            status = 'UNKNOWN'
        else:
            status = 'SAFE' if all(self.hit.values()) else 'NOT_CERTIFIED'
        return {'status':status, 'attempts':self.attempts,'resolved':self.resolved,
                'missing':self.missing, 'wealth':dict(self.wealth),
                'path_hits':dict(self.hit),'first_hit':dict(self.first_hit)}
